using Poly.Interpretation.CSharp;

namespace Poly.Tests.Interpretation;

/// <summary>
/// E-01 (#685): <see cref="CSharpWriter.Write(CompilationUnitNode)"/> prints one
/// deterministic header — an auto-generated banner, exactly one nullable directive,
/// and explicit-plus-inferred usings sorted System-first — and
/// <see cref="CSharpReader"/> consumes the banner so <c>Write(Read(x))</c> holds.
/// The <c>Write(typeDefs)</c> overload stays header-identical until E-03.
/// </summary>
public class CSharpWriterUnitTests {
    private const string Banner = "// <auto-generated/>";

    private static int Occurrences(string text, string token) {
        var count = 0;
        for (var index = text.IndexOf(token, StringComparison.Ordinal);
             index >= 0;
             index = text.IndexOf(token, index + token.Length, StringComparison.Ordinal))
            count++;
        return count;
    }

    private static int CountComments(Node node, string text) {
        var count = node is Comment comment && comment.Text == text ? 1 : 0;
        foreach (var child in node.Children) {
            if (child is not null)
                count += CountComments(child, text);
        }
        return count;
    }

    private static CompilationUnitNode Unit(string? ns, IReadOnlyList<string> usings, params TypeDefinitionNode[] types) =>
        new(usings, ns, types, TopLevelStatements: null);

    private static TypeDefinitionNode ClassWithDateAndList() => new(
        "Cart",
        Fields: [
            new FieldDefinitionNode(
                "Items",
                new NamedTypeReference("List", TypeArguments: [
                    new PrimitiveTypeReference(Poly.Introspection.PrimitiveType.Int32),
                ])),
            new FieldDefinitionNode("PlacedOn", new NamedTypeReference("DateOnly")),
        ]);

    [Test]
    public async Task Write_Unit_InfersMergesAndSortsUsings_OneNullableHeader() {
        var unit = Unit(
            "Demo.Shop",
            ["System.Text.Json", "SystemTools.X", "Poly.Generated"],
            ClassWithDateAndList());

        var text = CSharpLanguage.Write(unit);

        var expectedHeader =
            "// <auto-generated/>\n" +
            "\n" +
            "#nullable enable\n" +
            "\n" +
            "using System;\n" +
            "using System.Collections.Generic;\n" +
            "using System.Text.Json;\n" +
            "using Poly.Generated;\n" +
            "using SystemTools.X;\n" +
            "\n" +
            "namespace Demo.Shop;\n" +
            "\n";
        await Assert.That(text.StartsWith(expectedHeader, StringComparison.Ordinal)).IsTrue()
            .Because(text);
        await Assert.That(Occurrences(text, "#nullable enable")).IsEqualTo(1);
        await Assert.That(Occurrences(text, Banner)).IsEqualTo(1);
        await Assert.That(Occurrences(text, "using System;")).IsEqualTo(1);
        await Assert.That(Occurrences(text, "using System.Collections.Generic;")).IsEqualTo(1);
    }

    [Test]
    public async Task Write_Unit_EmptyUsings_HeaderShape() {
        var text = CSharpLanguage.Write(Unit("Demo", [], new TypeDefinitionNode("Empty")));

        // Exactly one blank line between the directive and the namespace: no double gap.
        await Assert.That(
            text.StartsWith("// <auto-generated/>\n\n#nullable enable\n\nnamespace Demo;\n\npublic class Empty", StringComparison.Ordinal))
            .IsTrue().Because(text);
        await Assert.That(Occurrences(text, "\n\n\n")).IsEqualTo(0);
    }

    [Test]
    public async Task Write_Unit_BannerMarksFileGenerated() {
        var text = CSharpLanguage.Write(Unit("Demo", ["System"], new TypeDefinitionNode("Empty")));

        await Assert.That(text.StartsWith(Banner + "\n", StringComparison.Ordinal)).IsTrue().Because(text);
        await Assert.That(text.Contains("Requires:", StringComparison.Ordinal)).IsFalse();
    }

    [Test]
    public async Task Write_TypeDefs_HeaderIsUnchangedUntilE03() {
        // PIN: green before and after E-01. E-03 flips this overload to the unit header.
        var text = CSharpLanguage.Write([new TypeDefinitionNode("Empty")]);

        await Assert.That(text.StartsWith("#nullable enable\n", StringComparison.Ordinal)).IsTrue().Because(text);
        await Assert.That(text.Contains(Banner, StringComparison.Ordinal)).IsFalse();
        await Assert.That(Occurrences(text, "#nullable enable")).IsEqualTo(1);
    }

    [Test]
    public async Task Write_Read_Write_IsIdempotent_WithBanner() {
        const string source =
            "// <auto-generated/>\n" +
            "\n" +
            "#nullable enable\n" +
            "\n" +
            "namespace Demo;\n" +
            "\n" +
            "public class C\n" +
            "{\n" +
            "    public void M()\n" +
            "    {\n" +
            "        var x = 1;\n" +
            "    }\n" +
            "}";

        var once = CSharpLanguage.Write(CSharpLanguage.Read(source));
        var twice = CSharpLanguage.Write(CSharpLanguage.Read(once));

        await Assert.That(once.StartsWith(Banner + "\n", StringComparison.Ordinal)).IsTrue().Because(once);
        await Assert.That(Occurrences(once, Banner)).IsEqualTo(1).Because(once);
        await Assert.That(once.IndexOf(Banner, StringComparison.Ordinal))
            .IsLessThan(once.IndexOf("class C", StringComparison.Ordinal));
        await Assert.That(twice).IsEqualTo(once);
    }

    [Test]
    public async Task Read_LeadingNonBannerComment_IsKept() {
        // PIN: green before and after E-01. Only the generated banner is header trivia.
        const string source =
            "// keep me\n" +
            "\n" +
            "public class C\n" +
            "{\n" +
            "    public void M()\n" +
            "    {\n" +
            "        var x = 1;\n" +
            "    }\n" +
            "}";

        var unit = CSharpLanguage.Read(source);

        await Assert.That(CountComments(unit, "keep me")).IsEqualTo(1);
    }

    [Test]
    public async Task Read_BannerNotAtLine1Col1_StaysAComment() {
        // PIN: green before and after E-01. An offset banner is an ordinary comment.
        const string source =
            "\n" +
            "// <auto-generated/>\n" +
            "\n" +
            "public class C\n" +
            "{\n" +
            "    public void M()\n" +
            "    {\n" +
            "        var x = 1;\n" +
            "    }\n" +
            "}";

        var unit = CSharpLanguage.Read(source);

        await Assert.That(CountComments(unit, "<auto-generated/>")).IsEqualTo(1);
    }

    [Test]
    public async Task Write_Unit_UsingThatIsNotADottedName_Throws() {
        var unit = Unit(null, ["@shop"], new TypeDefinitionNode("Empty"));

        await Assert.That(() => CSharpLanguage.Write(unit))
            .Throws<InvalidOperationException>()
            .WithMessageContaining("@shop");
    }

    [Test]
    [Arguments("Shop.class")]
    [Arguments("global::Shop")]
    [Arguments("@shop")]
    public async Task Write_Unit_NamespaceThatIsNotADottedName_Throws(string ns) {
        var unit = Unit(ns, [], new TypeDefinitionNode("Empty"));

        await Assert.That(() => CSharpLanguage.Write(unit))
            .Throws<InvalidOperationException>()
            .WithMessageContaining(ns);
    }
}